class Solution:
    def maximumRemovals(self, s: str, p: str, removable: List[int]) -> int:
        n, m = len(s), len(p)
        removed = [False] * n

        def ok():
            j = 0
            for i in range(n):
                if j == m:
                    break
                if removed[i] or s[i] != p[j]:
                    continue
                j += 1
            return j == m

        for k, idx in enumerate(removable):
            removed[idx] = True
            if not ok():
                return k
        return len(removable)

