class Solution {
    private boolean[] removed;
    private String s, p;

    public int maximumRemovals(String s, String p, int[] removable) {
        this.s = s;
        this.p = p;
        this.removed = new boolean[s.length()];
        int lo = 0, hi = removable.length;
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            if (check(removable, mid)) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }

    private boolean check(int[] removable, int cnt) {
        Arrays.fill(removed, false);
        for (int i = 0; i < cnt; i++) removed[removable[i]] = true;
        int j = 0;
        for (int i = 0; i < s.length() && j < p.length(); i++)
            if (!removed[i] && s.charAt(i) == p.charAt(j)) j++;
        return j == p.length();
    }
}

